import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Getting started","description":"Pidrang turns the tables of a Supabase project into an Angular admin: a list, create, show and edit page for each table, with sign-in. pidrang init reads...","frontmatter":{"description":"Pidrang turns the tables of a Supabase project into an Angular admin: a list, create, show and edit page for each table, with sign-in. pidrang init reads..."},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function s(r,e,d,h,l,c){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Pidrang turns the tables of a Supabase project into an Angular admin: a list, create, show and edit page for each table, with sign-in. <code>pidrang init</code> reads your schema and generates it. This page sets up a new app, then an existing one; to write the pages by hand instead, see <a href="./manual-setup">Write the pages yourself</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Node.js 22.22.3 or a later 22.x, 24.15.0 or a later 24.x, or 26 and later. <code>pidrang init</code> checks it and stops with a plain message on anything else.</li><li>An Angular 22.1 or a later 22.x application using standalone APIs and the router, as <code>ng new</code> creates it.</li><li>A Supabase project with at least one table that has an <code>id</code> primary key column. Pidrang assumes <code>id</code> on every table; composite or differently named keys are not supported.</li><li>The project URL and the publishable key (formerly anon, <code>sb_publishable_...</code>), shown by the Connect button at the top of the Supabase dashboard.</li></ul><p>Two working examples show the result: <a href="https://pidrang.dev/demo-material/" target="_blank" rel="noreferrer">demo-material</a> and <a href="https://pidrang.dev/demo-tailwind/" target="_blank" rel="noreferrer">demo-tailwind</a>, the same three resources on the two UI layers, listed at <a href="https://pidrang.dev/demos/" target="_blank" rel="noreferrer">pidrang.dev/demos</a>.</p><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose your path&quot;">​</a></h2><ul><li><strong>New app</strong>: an app just created by <code>ng new</code>. <code>init</code> generates and wires everything, including a layout with a menu of the tables.</li><li><strong>Existing app</strong>: an app with its own pages and routes. <code>init</code> adds the pages and the routes next to yours, and leaves the entry of the app to you.</li><li><strong>No CLI</strong>: <a href="./manual-setup">Write the pages yourself</a> with the same components.</li></ul><p><code>init</code> treats an app as new when <code>src/app/app.html</code> still holds the welcome page of <code>ng new</code> and <code>app.routes.ts</code> declares no route. Anything else is an existing app.</p><h2 id="new-app" tabindex="-1">New app <a class="header-anchor" href="#new-app" aria-label="Permalink to &quot;New app&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-admin</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-admin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pidrang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p><code>init</code> asks, in order:</p><ol><li>The project URL of your Supabase project.</li><li>How to read your table definitions: the secret key, a direct database connection, or GraphQL with the publishable key. The secret key and the database password are used to read the schema only; <code>init</code> does not write them into the app.</li><li>The tables to scaffold, the actions each one supports (list, create, show, edit, delete) and the fields to hide.</li><li>Whether to add the navigation layout and the sign-in page, both yes by default, and whether your tables need a signed-in user to be read.</li><li>Whether to install the packages the app is missing among <code>@pidrang/core</code>, <code>@pidrang/supabase</code>, <code>@supabase/supabase-js</code> and <code>@pidrang/material</code>, and to run <code>ng add @angular/material</code>.</li></ol><p>It writes <code>src/environments/environment.ts</code> and <code>environment.development.ts</code> with your project URL and a placeholder for the key. Replace <code>supabasePublishableKey</code> in both with the publishable key of the project: the app runs in the browser, so never put the secret key or the database password there.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Open <code>http://localhost:4200</code>. The app opens on the list of the first table you picked, or on the sign-in page when your tables need a signed-in user to be read. The menu of the layout lists the tables, and its Sign in link opens <code>/sign-in</code>.</p><p>What <code>init</code> wrote:</p><ul><li><code>src/app/resources.ts</code>: one <code>Resource</code> per table, with its typed fields. Edit it to rename a label, hide a field or turn an action off.</li><li><code>src/app/resource-routes.ts</code>: the routes <code>:resource</code>, <code>:resource/create</code>, <code>:resource/:id</code> and <code>:resource/:id/edit</code>, with their guards, and the <code>sign-in</code> route.</li><li><code>src/app/pages/</code> and <code>src/app/pidrang/</code>: the List, Create, Show, Edit and sign-in pages, and the helpers they call.</li><li><code>src/app/layout/</code>: the navigation layout.</li><li><code>app.config.ts</code>, <code>app.routes.ts</code> and <code>app.html</code>, edited to register Pidrang, add the routes and host the layout.</li></ul><p>The pages are rendered with Angular Material. The layout follows the UI layer of the app: Tailwind when <code>package.json</code> declares <code>@pidrang/tailwind</code>, Angular Material otherwise. Every file and every option is in <a href="./reference/cli">the CLI reference</a>.</p><h2 id="existing-app" tabindex="-1">Existing app <a class="header-anchor" href="#existing-app" aria-label="Permalink to &quot;Existing app&quot;">​</a></h2><p>From the workspace root of the app:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pidrang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>It asks the same questions, except the layout, which an existing app never gets, and the sign-in page, which it writes unless <code>app.routes.ts</code> already declares a <code>sign-in</code> route. Then it:</p><ul><li>Writes <code>resources.ts</code>, <code>resource-routes.ts</code>, the pages and the helpers, as on a new app. A file that already exists with other content stops <code>init</code> before it writes anything, and lists the paths: move or rename yours, then run it again.</li><li>Adds <code>...resourceRoutes</code> at the top of the routes array of <code>app.routes.ts</code>, and registers Pidrang and <code>withComponentInputBinding()</code> in <code>app.config.ts</code>.</li><li>Replaces the welcome page of <code>app.html</code> with <code>&lt;router-outlet /&gt;</code>, and leaves a template that already has an outlet as it is.</li><li>Writes the environment files when the app has none. When it has, <code>init</code> prints the <code>supabaseUrl</code> and <code>supabasePublishableKey</code> lines to add to <code>src/environments/environment.ts</code>.</li></ul><p>When a file cannot be edited safely, <code>init</code> adds a <code>pidrang</code> comment at its top that lists the exact change to make.</p><p>Two things stay with you:</p><ul><li><strong>The entry of the app.</strong> Your own <code>&#39;&#39;</code> route keeps opening your home page. When the app has none, <code>init</code> prints the redirect to add above your other routes, for example <code>{ path: &#39;&#39;, pathMatch: &#39;full&#39;, redirectTo: &#39;/products&#39; }</code>. The generated pages are at <code>/&lt;table&gt;</code> either way.</li><li><strong>The sign-in guard.</strong> For the tables that need a signed-in user to be read, <code>init</code> adds the guard only on a new app, or extends the one an earlier run wrote. On an existing app it names those tables instead; see <a href="./authentication#guards-on-the-generated-routes">Guards on the generated routes</a>.</li></ul><p>To add a table later, run <code>init</code> again: see <a href="./reference/cli#a-second-run">A second run</a>.</p><h2 id="row-level-security" tabindex="-1">Row Level Security <a class="header-anchor" href="#row-level-security" aria-label="Permalink to &quot;Row Level Security&quot;">​</a></h2><p><code>@pidrang/supabase</code> performs no authorization. Every guarantee comes from your Supabase RLS policies — see <a href="./authentication#row-level-security">Row Level Security</a>.</p><h2 id="choosing-a-ui-layer" tabindex="-1">Choosing a UI layer <a class="header-anchor" href="#choosing-a-ui-layer" aria-label="Permalink to &quot;Choosing a UI layer&quot;">​</a></h2><p><code>@pidrang/material</code> and <code>@pidrang/tailwind</code> expose the same components, with different styling. Material needs a Material theme; Tailwind ships no CSS and needs a <code>@source</code> line in your global stylesheet. See <a href="./ui-layers/">UI layers</a>, and <a href="./ui-layers/material">Angular Material</a> or <a href="./ui-layers/tailwind">Tailwind CSS</a> for the setup of each one.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>The app still shows the Angular welcome page: <code>app.html</code> still holds it. Init replaces that template with <code>&lt;router-outlet /&gt;</code> or the navigation layout; if you had already changed the file and it has no outlet, the page renders nothing below your content, so add <code>&lt;router-outlet /&gt;</code> where the pages should appear.</p><p><code>ng build</code> warns that the initial bundle exceeded its budget: the budget <code>ng new</code> sets warns above 500 kB, and an app with the Supabase client, Angular Material and the layout starts above it (about 690 kB with the layout) even though the pages load lazily. It is a warning, the build succeeds; raise <code>maximumWarning</code> in the <code>budgets</code> of <code>angular.json</code> if you want it gone.</p><p>The Sign in button does nothing and the console shows the router error <code>NG04002</code> (<code>Cannot match any routes. URL Segment: &#39;sign-in&#39;</code> in a development build): <code>provideSignInPath(&#39;/sign-in&#39;)</code> is set but no sign-in page is, and the resource routes do not match a name that is not a resource. Run <code>pidrang generate auth</code>, add your own sign-in page at <code>/sign-in</code>, or change the path in <code>app.config.ts</code>.</p><p>The URL changes but a page stays blank: <code>provideRouter</code> has no <code>withComponentInputBinding()</code>. The pages read <code>:resource</code> and <code>:id</code> from their inputs and render nothing without it. Init adds it to the existing <code>provideRouter(...)</code> call; if your app config could not be edited, the <code>// pidrang:</code> comment at the top of the file shows the line to write.</p><p><code>/products</code> opens the not-found route: <code>...resourceRoutes</code> is missing from <code>routes</code>, or sits below a <code>**</code> route, which matches everything. It belongs at the top of the array, with your fixed paths after it.</p><p>The table is empty: see <a href="./authentication#troubleshooting">Authentication troubleshooting</a> — RLS on read-only tables, missing guards, or an unsigned-in user on a private table.</p><p>Saving says you may need to sign in, or returns a permission error: see <a href="./authentication#troubleshooting">Authentication troubleshooting</a> — plain text sign-in prompt when <code>provideSignInPath</code> is not configured, or RLS denying access after login.</p><p>Requests fail with an invalid API key or do not reach Supabase: <code>supabaseUrl</code> and <code>supabasePublishableKey</code> in <code>src/environments/environment.ts</code> are still the placeholders, point to another project, or hold a key that was rotated. Both values are shown by the Connect button at the top of your project&#39;s Supabase dashboard; use the publishable key (formerly anon), never the secret key or the database password.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./manual-setup">Write the pages yourself</a>: the same pages built by hand, step by step.</li><li><a href="./architecture">Architecture</a>: how core, the data providers and the UI layers fit together.</li><li><a href="https://github.com/pidrang/pidrang/blob/main/ROADMAP.md" target="_blank" rel="noreferrer"><code>ROADMAP.md</code></a>: what is planned.</li><li><a href="https://github.com/pidrang/pidrang/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a>: how to contribute.</li></ul>`,42)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
